<?php

declare(strict_types=1);namespace frontend\controllers;use common\models\{SupportTicket,SupportMessage,SupportAttachment};use frontend\components\Controller;use frontend\models\{TicketForm,ReplyForm};use Yii;use yii\filters\AccessControl;use yii\web\UploadedFile;use yii\web\NotFoundHttpException;
final class SupportController extends Controller
{
 public function behaviors():array{return ['access'=>['class'=>AccessControl::class,'rules'=>[['allow'=>true,'roles'=>['@']]]]];}
 public function actionIndex():string{return $this->render('index',['tickets'=>SupportTicket::find()->where(['user_id'=>Yii::$app->user->id])->orderBy(['updated_at'=>SORT_DESC])->all()]);}
 public function actionCreate(){ $m=new TicketForm();if($m->load(Yii::$app->request->post())){$m->attachments=UploadedFile::getInstances($m,'attachments');if($m->validate()){$tx=Yii::$app->db->beginTransaction();try{$t=new SupportTicket(['user_id'=>Yii::$app->user->id,'subject'=>$m->subject,'status'=>SupportTicket::STATUS_OPEN,'created_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')]);$t->save(false);$msg=new SupportMessage(['ticket_id'=>$t->id,'user_id'=>Yii::$app->user->id,'body'=>$m->message,'is_staff'=>0,'created_at'=>date('Y-m-d H:i:s')]);$msg->save(false);$this->saveAttachments($msg,$m->attachments);$tx->commit();return $this->redirect(['view','id'=>$t->id]);}catch(\Throwable $e){$tx->rollBack();throw $e;}}}return $this->render('create',['model'=>$m]);}
 public function actionAttachment(int $id){$a=SupportAttachment::findOne($id);if(!$a)throw new NotFoundHttpException();$msg=SupportMessage::findOne($a->message_id);$t=$msg?SupportTicket::findOne($msg->ticket_id):null;if(!$t||$t->user_id!=(int)Yii::$app->user->id)throw new NotFoundHttpException();$path=Yii::getAlias('@storage/uploads/support/'.$a->stored_name);if(!is_file($path))throw new NotFoundHttpException();return Yii::$app->response->sendFile($path,$a->original_name,['mimeType'=>$a->mime_type,'inline'=>false]);}
 public function actionView(int $id){$t=SupportTicket::findOne(['id'=>$id,'user_id'=>Yii::$app->user->id]);if(!$t)throw new NotFoundHttpException();$m=new ReplyForm();if($m->load(Yii::$app->request->post())&&$m->validate()&&$t->status!==SupportTicket::STATUS_CLOSED){$msg=new SupportMessage(['ticket_id'=>$t->id,'user_id'=>Yii::$app->user->id,'body'=>$m->message,'is_staff'=>0,'created_at'=>date('Y-m-d H:i:s')]);$msg->save(false);$t->status=SupportTicket::STATUS_OPEN;$t->updated_at=date('Y-m-d H:i:s');$t->save(false,['status','updated_at']);return $this->refresh();}return $this->render('view',['ticket'=>$t,'model'=>$m]);}
 private function saveAttachments(SupportMessage $msg,array $files):void{$dir=Yii::getAlias('@storage/uploads/support');if(!is_dir($dir))mkdir($dir,0770,true);foreach($files as $f){$stored=bin2hex(random_bytes(16)).'.'.strtolower($f->extension);if($f->saveAs($dir.'/'.$stored)){$a=new SupportAttachment(['message_id'=>$msg->id,'stored_name'=>$stored,'original_name'=>$f->name,'mime_type'=>$f->type?:'application/octet-stream','size'=>$f->size,'created_at'=>date('Y-m-d H:i:s')]);$a->save(false);}}}
}
